@* Vertical tab navigation for settings sections *@

<nav class="settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
            <span class="sidebar-icon">@GetIcon(section)</span>
            <span class="sidebar-label">@section</span>
        </button>
    }
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@* Profile editing section *@

<div class="settings-section">
    <h2>Profile</h2>

    <div class="profile-avatar-area">
        <div class="avatar-preview">
            @if (!string.IsNullOrEmpty(editDisplayName))
            {
                <img src="@editAvatarUrl" alt="Avatar" class="avatar-image" />
            }
        </div>
        <p class="avatar-url-display">@editAvatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="editDisplayName" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="editEmail" class="form-control" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="editBio" class="form-control" rows="4"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
        <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (showSuccess)
    {
        <div class="toast-success">Profile saved successfully!</div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile? Profile { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private string editDisplayName = "";
    private string editEmail = "";
    private string editAvatarUrl = "";
    private string editBio = "";
    private bool showSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !hasInitialized)
        {
            LoadFromProfile();
            hasInitialized = true;
        }
    }

    private bool hasInitialized;

    private void LoadFromProfile()
    {
        if (Profile is null) return;
        editDisplayName = Profile.DisplayName;
        editEmail = Profile.Email;
        editAvatarUrl = Profile.AvatarUrl;
        editBio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
        await OnSave.InvokeAsync(updated);
        showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        LoadFromProfile();
    }
}

@* Notification preferences section *@

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="emailNotifications" />
            <span>Email Notifications</span>
        </label>

        <label class="toggle-label">
            <input type="checkbox" @bind="pushNotifications" />
            <span>Push Notifications</span>
        </label>

        <label class="toggle-label">
            <input type="checkbox" @bind="weeklyDigest" />
            <span>Weekly Digest</span>
        </label>
    </div>

    @if (channels.Count > 0)
    {
        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in channels)
            {
                <label class="toggle-label">
                    <input type="checkbox"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <span>@channel</span>
                </label>
            }
        </div>
    }

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs? Prefs { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    [Parameter]
    public List<string> AvailableChannels { get; set; } = ["general", "announcements", "updates", "marketing", "alerts"];

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> channels = new();
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !hasInitialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            channels = AvailableChannels;
            hasInitialized = true;
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
    }
}

@* Security settings section *@

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
            <span>Change Password</span>
            <span class="expand-icon">@(passwordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="currentPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="newPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="confirmPassword" class="form-control" />
                </div>

                @if (!string.IsNullOrEmpty(passwordError))
                {
                    <div class="error-message">@passwordError</div>
                }
                @if (passwordSuccess)
                {
                    <div class="toast-success">Password updated successfully!</div>
                }

                <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="tfa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                @(TwoFactorEnabled ? "● Enabled" : "○ Disabled")
            </span>
            <label class="toggle-label">
                <input type="checkbox" checked="@TwoFactorEnabled" @onchange="OnTwoFactorToggle" />
                <span>Enable 2FA</span>
            </label>
        </div>
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        @if (Sessions?.Count > 0)
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }
        else
        {
            <p>No active sessions found.</p>
        }
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn btn-danger" @onclick="RevokeConfirmedAsync">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public bool TwoFactorEnabled { get; set; }

    [Parameter]
    public DateTime? LastPasswordChange { get; set; }

    [Parameter, EditorRequired]
    public List<ActiveSession>? Sessions { get; set; }

    [Parameter]
    public string CurrentSessionId { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<bool> OnTwoFactorChanged { get; set; }

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool passwordSuccess;
    private ActiveSession? sessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        passwordSuccess = true;
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
    }

    private async Task OnTwoFactorToggle(ChangeEventArgs e)
    {
        var enabled = (bool)(e.Value ?? false);
        await OnTwoFactorChanged.InvokeAsync(enabled);
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeConfirmedAsync()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }
}

@* Appearance settings section with live preview *@

<div class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme Selector -->
    <div class="form-group">
        <label><strong>Theme</strong></label>
        <div class="radio-group">
            <label class="radio-label">
                <input type="radio" name="theme" value="Light"
                       checked="@(selectedTheme == "Light")"
                       @onchange="@(() => selectedTheme = "Light")" />
                <span>Light</span>
            </label>
            <label class="radio-label">
                <input type="radio" name="theme" value="Dark"
                       checked="@(selectedTheme == "Dark")"
                       @onchange="@(() => selectedTheme = "Dark")" />
                <span>Dark</span>
            </label>
            <label class="radio-label">
                <input type="radio" name="theme" value="System"
                       checked="@(selectedTheme == "System")"
                       @onchange="@(() => selectedTheme = "System")" />
                <span>System</span>
            </label>
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="form-group">
        <label><strong>Font Size</strong></label>
        <div class="radio-group">
            <label class="radio-label">
