{"path": "/tmp/sv-f611be7abf5c4b12910e02b8ec932e48/Components/Pages/Settings/SecuritySection.razor", "file_text": "@* Security settings section *@

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
            <span>Change Password</span>
            <span class="expand-icon">@(passwordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="currentPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="newPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="confirmPassword" class="form-control" />
                </div>

                @if (!string.IsNullOrEmpty(passwordError))
                {
                    <div class="error-message">@passwordError</div>
                }
                @if (passwordSuccess)
                {
                    <div class="toast-success">Password updated successfully!</div>
                }

                <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="tfa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                @(TwoFactorEnabled ? "● Enabled" : "○ Disabled")
            </span>
            <label class="toggle-label">
                <input type="checkbox" checked="@TwoFactorEnabled" @onchange="OnTwoFactorToggle" />
                <span>Enable 2FA</span>
            </label>
        </div>
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        @if (Sessions?.Count > 0)
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }
        else
        {
            <p>No active sessions found.</p>
        }
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn btn-danger" @onclick="RevokeConfirmedAsync">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public bool TwoFactorEnabled { get; set; }

    [Parameter]
    public DateTime? LastPasswordChange { get; set; }

    [Parameter, EditorRequired]
    public List<ActiveSession>? Sessions { get; set; }

    [Parameter]
    public string CurrentSessionId { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<bool> OnTwoFactorChanged { get; set; }

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool passwordSuccess;
    private ActiveSession? sessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        passwordSuccess = true;
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
    }

    private async Task OnTwoFactorToggle(ChangeEventArgs e)
    {
        var enabled = (bool)(e.Value ?? false);
        await OnTwoFactorChanged.InvokeAsync(enabled);
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeConfirmedAsync()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }
}
"}

{"path": "/tmp/sv-f611be7abf5c4b12910e02b8ec932e48/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@* Appearance settings section with live preview *@

<div class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme Selector -->
    <div class="form-group">
        <label><strong>Theme</strong></label>
        <div class="radio-group">
            <label class="radio-label">
                <input type="radio" name="theme" value="Light"
                       checked="@(selectedTheme == "Light")"
                       @onchange="@(() => selectedTheme = "Light")" />
                <span>Light</span>
            </label>
            <label class="radio-label">
                <input type="radio" name="theme" value="Dark"
                       checked="@(selectedTheme == "Dark")"
                       @onchange="@(() => selectedTheme = "Dark")" />
                <span>Dark</span>
            </label>
            <label class="radio-label">
                <input type="radio" name="theme" value="System"
                       checked="@(selectedTheme == "System")"
                       @onchange="@(() => selectedTheme = "System")" />
                <span>System</span>
            </label>
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="form-group">
        <label><strong>Font Size</strong></label>
        <div class="radio-group">
            <label class="radio-label">
                <input type="radio" name="fontSize" value="Small"
                       checked="@(selectedFontSize == "Small")"
                       @onchange="@(() => selectedFontSize = "Small")" />
                <span>Small</span>
            </label>
            <label class="radio-label">
                <input type="radio" name="fontSize" value="Medium"
                       checked="@(selectedFontSize == "Medium")"
                       @onchange="@(() => selectedFontSize = "Medium")" />
                <span>Medium</span>
            </label>
            <label class="radio-label">
                <input type="radio" name="fontSize" value="Large"
                       checked="@(selectedFontSize == "Large")"
                       @onchange="@(() => selectedFontSize = "Large")" />
                <span>Large</span>
            </label>
        </div>
    </div>

    <!-- Language Dropdown -->
    <div class="form-group">
        <label for="language"><strong>Language</strong></label>
        <select id="language" @bind="selectedLanguage" class="form-control">
            <option value="en">English</option>
            <option value="es">Español</option>
            <option value="fr">Français</option>
            <option value="de">Deutsch</option>
            <option value="ja">日本語</option>
            <option value="zh">中文</option>
        </select>
    </div>

    <!-- Compact Mode Toggle -->
    <div class="form-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="compactMode" />
            <span><strong>Compact Mode</strong></span>
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Here is some sample text to demonstrate the appearance.</p>
            <button class="btn btn-primary">Sample Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings? Settings { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !hasInitialized)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
            hasInitialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        var theme = selectedTheme.ToLowerInvariant();
        var font = $"font-{selectedFontSize.ToLowerInvariant()}";
        var compact = compactMode ? "compact" : "";
        return $"theme-{theme} {font} {compact}";
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
    }
}
"}

