{"file_text": ".settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    background: var(--sidebar-bg, #f8f9fa);
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    display: flex;
    flex-direction: column;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.95rem;
    color: #495057;
    text-align: left;
    width: 100%;
    transition: background-color 0.15s, color 0.15s;
}

.sidebar-item:hover {
    background: #e9ecef;
}

.sidebar-item.active {
    background: #0d6efd;
    color: white;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.5rem;
    border-bottom: 2px solid #dee2e6;
}

/* Forms */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    line-height: 1.5;
}

.form-control:focus {
    border-color: #86b7fe;
    outline: 0;
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
}

.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn {
    padding: 0.5rem 1rem;
    border: 1px solid transparent;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    cursor: pointer;
    font-weight: 500;
    transition: background-color 0.15s;
}

.btn-primary {
    background: #0d6efd;
    color: white;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: white;
}

.btn-secondary:hover {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: white;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
}

/* Toggle labels */
.toggle-group,
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.toggle-label input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
}

/* Profile */
.profile-avatar-area {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-preview {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    background: #e9ecef;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    margin-bottom: 0.5rem;
}

.avatar-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-url-display {
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
}

/* Toast */
.toast-success {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    background: #d1e7dd;
    color: #0f5132;
    border-radius: 0.375rem;
    border: 1px solid #badbcc;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    margin-bottom: 1.5rem;
}

.panel-header {
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* Security */
.tfa-section {
    margin-bottom: 1.5rem;
}

.tfa-status {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.status-indicator {
    font-weight: 600;
}

.status-indicator.enabled {
    color: #198754;
}

.status-indicator.disabled {
    color: #6c757d;
}

.current-badge {
    font-size: 0.8rem;
    padding: 0.2rem 0.5rem;
    background: #e9ecef;
    border-radius: 0.25rem;
    color: #495057;
}

/* Sessions Table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #dee2e6;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    font-size: 0.85rem;
    text-transform: uppercase;
    color: #6c757d;
}

/* Error */
.error-message {
    color: #dc3545;
    margin-bottom: 0.75rem;
    font-size: 0.9rem;
}

/* Radio groups */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    cursor: pointer;
}

/* Appearance Preview */
.preview-area {
    margin: 1.5rem 0;
    padding: 1.5rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    transition: all 0.2s;
}

.preview-area.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-area.theme-system {
    background: #f0f0f0;
    color: #333;
}

.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

