+    background: #e9ecef;
+}
+
+.panel-body {
+    padding: 1rem;
+    border-top: 1px solid #dee2e6;
+}
+
+/* Security */
+.tfa-section {
+    margin-bottom: 1.5rem;
+}
+
+.tfa-status {
+    display: flex;
+    align-items: center;
+    gap: 1.5rem;
+}
+
+.status-indicator {
+    font-weight: 600;
+}
+
+.status-indicator.enabled {
+    color: #198754;
+}
+
+.status-indicator.disabled {
+    color: #6c757d;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    padding: 0.2rem 0.5rem;
+    background: #e9ecef;
+    border-radius: 0.25rem;
+    color: #495057;
+}
+
+/* Sessions Table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-top: 0.5rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #dee2e6;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    font-size: 0.85rem;
+    text-transform: uppercase;
+    color: #6c757d;
+}
+
+/* Error */
+.error-message {
+    color: #dc3545;
+    margin-bottom: 0.75rem;
+    font-size: 0.9rem;
+}
+
+/* Radio groups */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.25rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.375rem;
+    cursor: pointer;
+}
+
+/* Appearance Preview */
+.preview-area {
+    margin: 1.5rem 0;
+    padding: 1.5rem;
+    border: 1px solid #dee2e6;
+    border-radius: 0.5rem;
+    transition: all 0.2s;
+}
+
+.preview-area.theme-dark {
+    background: #1e1e1e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-area.theme-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+.preview-area.theme-system {
+    background: #f0f0f0;
+    color: #333;
+}
+
+.preview-area.font-small {
+    font-size: 0.8rem;
+}
+
+.preview-area.font-medium {
+    font-size: 1rem;
+}
+
+.preview-area.font-large {
+    font-size: 1.2rem;
+}
+
+.preview-area.compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+
+.preview-card {
+    margin-top: 1rem;
+    padding: 1rem;
+    border: 1px solid currentColor;
+    border-radius: 0.375rem;
+    opacity: 0.8;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    top: 0;
+    left: 0;
+    right: 0;
+    bottom: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1050;
+}
+
+.modal-dialog {
+    background: white;
+    border-radius: 0.5rem;
+    padding: 1.5rem;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
+}
+
+.modal-actions {
+    margin-top: 1.25rem;
+    display: flex;
+    gap: 0.75rem;
+    justify-content: flex-end;
+}
+
+/* Loading */
+.loading-spinner {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    height: 200px;
+    font-size: 1.1rem;
+    color: #6c757d;
+}
+

